import pandas as pd

def find_overlapping_shifts(employee_shifts: pd.DataFrame) -> pd.DataFrame:
    if employee_shifts.empty:
        return pd.DataFrame(columns=['employee_id', 'overlapping_shifts'])

    merged = employee_shifts.merge(employee_shifts, on='employee_id', suffixes=('_1', '_2'))
    overlapping = merged[
        (merged['start_time_1'] < merged['start_time_2']) &
        (merged['start_time_2'] < merged['end_time_1'])
    ]

    res = overlapping.groupby('employee_id', as_index=False).size()
    res.rename(columns={'size': 'overlapping_shifts'}, inplace=True)
    return res.sort_values(by='employee_id', ascending=True)
